import React, { useState, useRef } from 'react';

// FaEnvelope and FaPhoneAlt are no longer needed, so they are removed.

// --- STYLES ---
const styles = {
  contactSection: {
    backgroundColor: '#1a202c',
    padding: '80px 24px',
    fontFamily: 'sans-serif',
    color: '#e2e8f0',
    borderTop: '1px solid #2d3748',
  },
  // --- CHANGE 1: SIMPLIFIED the container to center the content ---
  container: {
    maxWidth: '700px', // Reduced width for a focused form layout
    margin: '0 auto',
    textAlign: 'center', // Center the title and subtitle
  },
  // The two-column styles (infoColumn, formColumn, etc.) are removed.
  title: {
    fontSize: '2.8rem',
    fontWeight: 'bold',
    color: '#ffffff',
    marginBottom: '16px',
    lineHeight: '1.2',
  },
  subtitle: {
    fontSize: '1.1rem',
    color: '#a0aec0',
    marginBottom: '48px',
  },
  // Form styles remain largely the same
  form: {
    display: 'flex',
    flexDirection: 'column',
    gap: '20px',
    textAlign: 'left', // Keep text inside inputs aligned left
  },
  input: {
    backgroundColor: '#2d3748',
    color: '#e2e8f0',
    border: '1px solid #4a5568',
    borderRadius: '12px', // More rounded corners to match the image
    padding: '16px',
    fontSize: '1rem',
    outline: 'none',
    transition: 'border-color 0.3s ease, box-shadow 0.3s ease',
  },
  textarea: {
    backgroundColor: '#2d3748',
    color: '#e2e8f0',
    border: '1px solid #4a5568',
    borderRadius: '12px', // More rounded corners
    padding: '16px',
    fontSize: '1rem',
    fontFamily: 'sans-serif',
    resize: 'vertical',
    minHeight: '150px', // Slightly taller
    outline: 'none',
    transition: 'border-color 0.3s ease, box-shadow 0.3s ease',
  },
  button: {
    backgroundColor: '#a7ffeb',
    color: '#1a202c',
    border: 'none',
    borderRadius: '12px', // More rounded corners
    padding: '18px', // Slightly taller button
    fontSize: '1rem',
    fontWeight: 'bold',
    cursor: 'pointer',
    marginTop: '16px',
    transition: 'opacity 0.3s ease',
  },
  statusMessage: { marginTop: '16px', padding: '10px', borderRadius: '8px', textAlign: 'center' },
  successMessage: { backgroundColor: '#28a745', color: 'white' },
  errorMessage: { backgroundColor: '#dc3545', color: 'white' }
};

// --- Updated Contact Section Component ---
const ContactSection = () => {
  const form = useRef();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState(null);

  const sendEmail = (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitStatus(null);

    // PASTE YOUR EMAILJS CREDENTIALS HERE
    emailjs.sendForm(
        'YOUR_SERVICE_ID',
        'YOUR_TEMPLATE_ID',
        form.current,
        'YOUR_PUBLIC_KEY'
      )
      .then((result) => {
          setSubmitStatus('success');
          setIsSubmitting(false);
          e.target.reset();
      }, (error) => {
          setSubmitStatus('error');
          setIsSubmitting(false);
      });
  };

  return (
    <section id="contact" style={styles.contactSection}>
      {/* --- CHANGE 2: REMOVED the two-column layout --- */}
      <div style={styles.container}>
        <h2 style={styles.title}>Get In Touch</h2>
        <p style={styles.subtitle}>
          Have questions or ready to start your health journey? Send a message, and I'll get back to you shortly.
        </p>

        <form ref={form} onSubmit={sendEmail} style={styles.form}>
          <input type="text" name="name" placeholder="Your Name" style={styles.input} required />
          <input type="email" name="email" placeholder="Your Email" style={styles.input} required />
          <textarea name="message" placeholder="Your Message" style={styles.textarea} required></textarea>
          <button type="submit" style={styles.button} disabled={isSubmitting}>
            {isSubmitting ? 'SENDING...' : 'SEND MESSAGE →'}
          </button>
          
          {submitStatus === 'success' && (
            <div style={{...styles.statusMessage, ...styles.successMessage}}>
              Thank you! Your message has been sent successfully.
            </div>
          )}
          {submitStatus === 'error' && (
            <div style={{...styles.statusMessage, ...styles.errorMessage}}>
              Something went wrong. Please try again later.
            </div>
          )}
        </form>
      </div>
    </section>
  );
};

export default ContactSection;
